class Solution {
    public int minDifference(int[] nums){
        if(nums.length<=4)return 0;
        Arrays.sort(nums);
        int answer=Integer.MAX_VALUE,n=nums.length;
        for(int i=0;i<=3;i++)answer=Math.min(answer,nums[n-4+i]-nums[i]);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minDifference(nums:IntArray):Int{
        if(nums.size<=4)return 0;
        nums.sort();
        return (0..3).minOf{
            nums[nums.size-4+it]-nums[it]
        }
    }
}

code.cpp:
class Solution {
    public: int minDifference(vector<int>& nums){
        if(nums.size()<=4)return 0;
        sort(nums.begin(),nums.end());
        int answer=INT_MAX,n=nums.size();
        for(int i=0;i<=3;++i)answer=min(answer,nums[n-4+i]-nums[i]);
        return answer;
    }
};
